<?php
$error=null;$edit=null;$canManage=has_role(['Admin','Receptionist']);
if(request_method('POST')){require_roles(['Admin','Receptionist']);try{verify_csrf();$action=post_string('action');if(in_array($action,['create','update'],true)){$name=post_string('full_name');$phone=post_string('phone');$dob=post_string('date_of_birth');$nid=post_string('national_id');$email=post_string('email');$approximateAge=post_string('approximate_age');$registrationType=post_string('registration_type','Normal');$patientStatus=post_string('status','Active');if(!in_array($registrationType,['Normal','Emergency'],true))throw new RuntimeException('Invalid registration type.');if(!in_array($patientStatus,['Active','Inactive'],true))throw new RuntimeException('Invalid patient status.');if($name===''||$phone==='')throw new RuntimeException('Patient name and phone are required.');if($dob!==''&&(!validate_date($dob)||$dob>date('Y-m-d')))throw new RuntimeException('Enter a valid date of birth.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid patient email address.');if($approximateAge!==''&&((int)$approximateAge<0||(int)$approximateAge>130))throw new RuntimeException('Approximate age must be between 0 and 130.');$pdo=db();if($action==='create'){$dup=$pdo->prepare("SELECT patient_code,full_name FROM patients WHERE (phone=? AND phone<>'') OR (national_id=? AND national_id<>'') OR (full_name=? AND date_of_birth=?) LIMIT 1");$dup->execute([$phone,$nid,$name,$dob?:null]);if($row=$dup->fetch())throw new RuntimeException('Possible duplicate found: '.$row['patient_code'].' — '.$row['full_name'].'. Review the existing record first.');$stmt=$pdo->prepare('INSERT INTO patients (full_name,date_of_birth,approximate_age,gender,blood_group,phone,email,address,emergency_contact_name,emergency_contact_relationship,emergency_contact_phone,national_id,registration_type,status,registered_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$name,nullable($dob),nullable($approximateAge),nullable(post_string('gender')),nullable(post_string('blood_group')),$phone,nullable($email),nullable(post_string('address')),nullable(post_string('emergency_contact_name')),nullable(post_string('emergency_contact_relationship')),nullable(post_string('emergency_contact_phone')),nullable($nid),$registrationType,'Active',current_user()['user_id']]);$id=(int)$pdo->lastInsertId();$code=code_from_id('PAT',$id);$pdo->prepare('UPDATE patients SET patient_code=? WHERE patient_id=?')->execute([$code,$id]);log_action('CREATE','patients',$id,null,['patient_code'=>$code,'full_name'=>$name]);}else{$id=(int)($_POST['patient_id']??0);$dup=$pdo->prepare("SELECT patient_code,full_name FROM patients WHERE patient_id<>? AND ((phone=? AND phone<>'') OR (national_id=? AND national_id<>'') OR (full_name=? AND date_of_birth=?)) LIMIT 1");$dup->execute([$id,$phone,$nid,$name,$dob?:null]);if($row=$dup->fetch())throw new RuntimeException('Possible duplicate found: '.$row['patient_code'].' — '.$row['full_name'].'. Review the existing record first.');$old=$pdo->prepare('SELECT * FROM patients WHERE patient_id=?');$old->execute([$id]);$before=$old->fetch();if(!$before)throw new RuntimeException('Patient record not found.');$stmt=$pdo->prepare('UPDATE patients SET full_name=?,date_of_birth=?,approximate_age=?,gender=?,blood_group=?,phone=?,email=?,address=?,emergency_contact_name=?,emergency_contact_relationship=?,emergency_contact_phone=?,national_id=?,registration_type=?,status=? WHERE patient_id=?');$stmt->execute([$name,nullable($dob),nullable($approximateAge),nullable(post_string('gender')),nullable(post_string('blood_group')),$phone,nullable($email),nullable(post_string('address')),nullable(post_string('emergency_contact_name')),nullable(post_string('emergency_contact_relationship')),nullable(post_string('emergency_contact_phone')),nullable($nid),$registrationType,$patientStatus,$id]);log_action('UPDATE','patients',$id,$before,$_POST);}
$patientId=$id;$allergyIds=array_map('intval',$_POST['allergy_ids']??[]);$pdo->prepare('DELETE FROM patient_allergies WHERE patient_id=?')->execute([$patientId]);$stmt=$pdo->prepare('INSERT INTO patient_allergies (patient_id,allergy_id,severity,notes) VALUES (?,?,?,?)');foreach($allergyIds as $aid)$stmt->execute([$patientId,$aid,post_string('allergy_severity','Unknown'),nullable(post_string('allergy_notes'))]);flash('patient','Patient saved successfully.','success');redirect_to('patients');}if($action==='toggle'){$id=(int)$_POST['patient_id'];db()->prepare("UPDATE patients SET status=IF(status='Active','Inactive','Active') WHERE patient_id=?")->execute([$id]);log_action('TOGGLE_STATUS','patients',$id);flash('patient','Patient status changed.','success');redirect_to('patients');}}catch(Throwable $e){$error=$e->getMessage();}}
if(isset($_GET['edit'])&&$canManage){$stmt=db()->prepare('SELECT * FROM patients WHERE patient_id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
$viewId=(int)($_GET['view']??0);$viewPatient=null;$timeline=[];if($viewId&&can_view_patient($viewId)){$stmt=db()->prepare("SELECT p.*,(SELECT GROUP_CONCAT(a.allergy_name ORDER BY a.allergy_name SEPARATOR ', ') FROM patient_allergies pa JOIN allergies a ON a.allergy_id=pa.allergy_id WHERE pa.patient_id=p.patient_id) allergies FROM patients p WHERE p.patient_id=?");$stmt->execute([$viewId]);$viewPatient=$stmt->fetch();$stmt=db()->prepare("SELECT 'Appointment' type,CONCAT(appointment_date,' ',start_time) event_date,CONCAT('Appointment ',appointment_number,' — ',status) label FROM appointments WHERE patient_id=? UNION ALL SELECT 'Consultation',consultation_date,CONCAT('Consultation — ',COALESCE(diagnosis,'No diagnosis')) FROM consultations WHERE patient_id=? UNION ALL SELECT 'Prescription',issued_at,CONCAT('Prescription ',prescription_number) FROM prescriptions WHERE patient_id=? UNION ALL SELECT 'Lab',requested_at,CONCAT('Lab request ',request_number,' — ',status) FROM lab_requests WHERE patient_id=? ORDER BY event_date DESC LIMIT 20");$stmt->execute([$viewId,$viewId,$viewId,$viewId]);$timeline=$stmt->fetchAll();}
$q=get_string('q');$params=[];$conditions=['1=1'];if(has_role('Doctor')){$doctorOwn=doctor_for_current_user();$conditions[]='EXISTS (SELECT 1 FROM appointments ax WHERE ax.patient_id=p.patient_id AND ax.doctor_id=?)';$params[]=$doctorOwn['doctor_id'];}if($q!==''){$conditions[]='(p.patient_code LIKE ? OR p.full_name LIKE ? OR p.phone LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}$where=implode(' AND ',$conditions);$stmt=db()->prepare("SELECT p.*,(SELECT GROUP_CONCAT(a.allergy_name ORDER BY a.allergy_name SEPARATOR ', ') FROM patient_allergies pa JOIN allergies a ON a.allergy_id=pa.allergy_id WHERE pa.patient_id=p.patient_id) allergies,(SELECT COUNT(*) FROM appointments ap WHERE ap.patient_id=p.patient_id) appointment_count FROM patients p WHERE $where ORDER BY p.created_at DESC LIMIT 100");$stmt->execute($params);$rows=$stmt->fetchAll();$allergies=db()->query("SELECT * FROM allergies WHERE status='Active' ORDER BY allergy_name")->fetchAll();$selected=[];if($edit){$stmt=db()->prepare('SELECT allergy_id FROM patient_allergies WHERE patient_id=?');$stmt->execute([$edit['patient_id']]);$selected=array_map('intval',array_column($stmt->fetchAll(),'allergy_id'));}
?>
<div class="page-header"><div><h2>Patient records</h2><p>Registration, contact details, medical warnings and visit history.</p></div><?php if($canManage):?><button class="btn btn-primary" data-modal-open="patientModal">＋ Register patient</button><?php endif;?></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($viewPatient):?><div class="grid grid-3 mb-2"><div class="card"><div style="text-align:center"><div class="avatar" style="width:70px;height:70px;font-size:25px;margin:auto"><?=e(strtoupper(substr($viewPatient['full_name'],0,1)))?></div><h3 class="mb-0"><?=e($viewPatient['full_name'])?></h3><p class="text-muted mt-0"><?=e($viewPatient['patient_code'])?></p></div><div class="divider"></div><p><strong>Phone:</strong> <?=e($viewPatient['phone']??'—')?></p><p><strong>Blood group:</strong> <?=e($viewPatient['blood_group']??'—')?></p><p><strong>Allergies:</strong> <span class="text-danger"><?=e($viewPatient['allergies']??'None recorded')?></span></p><a class="btn btn-light btn-block" href="<?=e(route_url('patients'))?>">Close details</a></div><div class="card" style="grid-column:span 2"><div class="card-header"><div><h3>Medical timeline</h3><p>Chronological activity across the patient journey.</p></div></div><?php if($timeline):?><div class="timeline"><?php foreach($timeline as $t):?><div class="timeline-item"><strong><?=e($t['label'])?></strong><small><?=e($t['type'])?> · <?=format_date($t['event_date'],'d M Y, h:i A')?></small></div><?php endforeach;?></div><?php else:?><div class="empty-state"><p>No clinical activity recorded.</p></div><?php endif;?></div></div><?php endif;?>
<div class="card"><div class="card-header"><div><h3>Patient directory</h3><p><?=count($rows)?> records shown.</p></div><form method="get" class="actions"><input type="hidden" name="page" value="patients"><input class="input" name="q" value="<?=e($q)?>" placeholder="Code, name or phone"><button class="btn btn-light">Search</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Patient</th><th>Contact</th><th>Age / Blood</th><th>Allergies</th><th>Visits</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="table-title"><?=e($r['full_name'])?></div><div class="table-subtitle"><?=e($r['patient_code'])?> · <?=e($r['registration_type'])?></div></td><td><?=e($r['phone']??'—')?><div class="table-subtitle"><?=e($r['email']??'')?></div></td><td><?=e($r['date_of_birth']?format_date($r['date_of_birth']):($r['approximate_age']?'~'.$r['approximate_age'].' years':'—'))?><div class="table-subtitle"><?=e($r['blood_group']??'')?></div></td><td><?=e($r['allergies']??'None')?></td><td><?=$r['appointment_count']?></td><td><span class="badge badge-<?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><div class="actions"><a class="btn btn-light btn-sm" href="<?=e(route_url('patients',['view'=>$r['patient_id']]))?>">View</a><?php if($canManage):?><a class="btn btn-light btn-sm" href="<?=e(route_url('patients',['edit'=>$r['patient_id']]))?>">Edit</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="patient_id" value="<?=$r['patient_id']?>"><button class="btn btn-warning btn-sm"><?=$r['status']==='Active'?'Disable':'Enable'?></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div>
<?php if($canManage):?><div class="modal-backdrop <?=($edit||isset($_GET['new']))?'open':''?>" id="patientModal"><div class="modal"><div class="modal-header"><h3><?=$edit?'Edit patient':'Register patient'?></h3><button class="close-btn" data-modal-close>×</button></div><form method="post"><div class="modal-body"><?=csrf_field()?><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="patient_id" value="<?=$edit['patient_id']?>"><?php endif;?><div class="form-grid"><div class="field"><label class="required">Full name</label><input class="input" name="full_name" value="<?=e($edit['full_name']??'')?>" required></div><div class="field"><label class="required">Phone</label><input class="input" name="phone" value="<?=e($edit['phone']??'')?>" required></div><div class="field"><label>Date of birth</label><input class="input" type="date" max="<?=date('Y-m-d')?>" name="date_of_birth" value="<?=e($edit['date_of_birth']??'')?>"></div><div class="field"><label>Approximate age</label><input class="input" type="number" min="0" max="130" name="approximate_age" value="<?=e($edit['approximate_age']??'')?>"></div><div class="field"><label>Gender</label><select class="select" name="gender"><option value="">Select</option><?php foreach(['Female','Male','Other','Unknown'] as $g):?><option <?=($edit['gender']??'')===$g?'selected':''?>><?=$g?></option><?php endforeach;?></select></div><div class="field"><label>Blood group</label><select class="select" name="blood_group"><option value="">Unknown</option><?php foreach(['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $b):?><option <?=($edit['blood_group']??'')===$b?'selected':''?>><?=$b?></option><?php endforeach;?></select></div><div class="field"><label>Email</label><input class="input" type="email" name="email" value="<?=e($edit['email']??'')?>"></div><div class="field"><label>National ID</label><input class="input" name="national_id" value="<?=e($edit['national_id']??'')?>"></div><div class="field"><label>Registration type</label><select class="select" name="registration_type"><option>Normal</option><option <?=($edit['registration_type']??'')==='Emergency'?'selected':''?>>Emergency</option></select></div><?php if($edit):?><div class="field"><label>Status</label><select class="select" name="status"><option>Active</option><option <?=$edit['status']==='Inactive'?'selected':''?>>Inactive</option></select></div><?php endif;?></div><div class="field"><label>Address</label><textarea class="textarea" name="address"><?=e($edit['address']??'')?></textarea></div><h4>Emergency contact</h4><div class="form-grid form-grid-3"><div class="field"><label>Name</label><input class="input" name="emergency_contact_name" value="<?=e($edit['emergency_contact_name']??'')?>"></div><div class="field"><label>Relationship</label><input class="input" name="emergency_contact_relationship" value="<?=e($edit['emergency_contact_relationship']??'')?>"></div><div class="field"><label>Phone</label><input class="input" name="emergency_contact_phone" value="<?=e($edit['emergency_contact_phone']??'')?>"></div></div><h4>Medical warnings</h4><div class="check-row"><?php foreach($allergies as $a):?><label class="check-card"><input type="checkbox" name="allergy_ids[]" value="<?=$a['allergy_id']?>" <?=in_array((int)$a['allergy_id'],$selected,true)?'checked':''?>> <span><?=e($a['allergy_name'])?></span></label><?php endforeach;?></div><div class="form-grid mt-2"><div class="field"><label>Severity</label><select class="select" name="allergy_severity"><option>Unknown</option><option>Mild</option><option>Moderate</option><option>High</option></select></div><div class="field"><label>Allergy notes</label><input class="input" name="allergy_notes"></div></div></div><div class="modal-footer"><a class="btn btn-light" href="<?=e(route_url('patients'))?>">Cancel</a><button class="btn btn-primary">Save patient</button></div></form></div></div><?php endif;?>
